// main-wait: the diag-mw-cs-spin poll and its counters, out of line so the window poll keeps its CFG (and PGO record)
// audio-cost: files/private-trace/diag-au-bits (bit 0), -pcm (bit 1), -pump (bit 2), -all (0-2) -> recomp_au_switches, polled
// at the window boundary like diag-imports-fast; RENDER_DIAG_AU logs the pump counters of the window that just ended.
[[gnu::noinline]] unsigned auSwitches() {
    const auto has=[](const char* n){return access(n,F_OK)==0;};
    const unsigned bits=(has(RECOMP_APP_PATH("/private-trace/diag-au-all"))?7u:0u)|
        (has(RECOMP_APP_PATH("/private-trace/diag-au-bits"))?1u:0u)|
        (has(RECOMP_APP_PATH("/private-trace/diag-au-pcm"))?2u:0u)|
        (has(RECOMP_APP_PATH("/private-trace/diag-au-pump"))?4u:0u);
    const unsigned was=::recomp_au_switches.exchange(bits,std::memory_order_relaxed);
    static unsigned long long skippedLast=0,decodedLast=0;
    const auto skipped=::recomp_au_pump_skipped.load(std::memory_order_relaxed),decoded=::recomp_au_pump_decoded.load(std::memory_order_relaxed);
    GLOG("RENDER_DIAG_AU switches=%u pump_skipped=%llu pump_decoded=%llu",was,skipped-skippedLast,decoded-decodedLast);
    skippedLast=skipped;decodedLast=decoded;
    return bits;
}
// audio-ahead (USER-APPROVED fidelity trade-off: bounded extra audio output latency): files/private-trace/diag-au-ahead (lead 2
// packets), diag-au-ahead-1 / -2 / -4 (the largest present wins) -> recomp_au_ahead::state().lead, polled at the window
// boundary like diag-au-*; RENDER_DIAG_AU_AHEAD logs the callback worker's counters of the window that just ended (lead =
// the setting that applied during it; inflight_ms = time-weighted frames in flight / 48 kHz: ON minus OFF = the mean added
// delay from a game event to its sound; lead_* = frames in flight at each callback, lat_* = each packet's production ->
// AAudio-read time (both ms); main_wait_ms = main's total parked time on engine-signalled handles in the window, both arms).
// Out of line: the window poll keeps its CFG (and PGO record).
[[gnu::noinline]] unsigned auAheadSwitch() {
    const auto has=[](const char* n){return access(n,F_OK)==0;};
    unsigned lead=0;
    if(has(RECOMP_APP_PATH("/private-trace/diag-au-ahead-1")))lead=1;
    if(has(RECOMP_APP_PATH("/private-trace/diag-au-ahead")) ||
       has(RECOMP_APP_PATH("/private-trace/diag-au-ahead-2")))lead=2;
    if(has(RECOMP_APP_PATH("/private-trace/diag-au-ahead-4")))lead=4;
    auto& s=recomp_au_ahead::state();
    const unsigned was=s.lead.exchange(lead,std::memory_order_relaxed);
    struct Last{unsigned long long callbacks,early,refused,hints,wakes,leadSum,latSum,latCount,latOverflow,mainWaits,mainWaitUs,starved,
                inFlightFrameUs,inFlightUs;};
    static Last last{};
    const Last now{s.callbacks.load(std::memory_order_relaxed),s.early.load(std::memory_order_relaxed),
        s.refused.load(std::memory_order_relaxed),s.hints.load(std::memory_order_relaxed),s.wakes.load(std::memory_order_relaxed),
        s.leadSumFrames.load(std::memory_order_relaxed),s.latSumUs.load(std::memory_order_relaxed),
        s.latCount.load(std::memory_order_relaxed),s.latOverflow.load(std::memory_order_relaxed),
        s.mainWaits.load(std::memory_order_relaxed),s.mainWaitUs.load(std::memory_order_relaxed),
        ::recomp_v250_audio_starved.load(std::memory_order_relaxed),s.inFlightFrameUs.load(std::memory_order_relaxed),
        s.inFlightUs.load(std::memory_order_relaxed)};
    const unsigned long long areaUs=now.inFlightUs-last.inFlightUs;
    const long long leadMax=s.leadMaxFrames.exchange(-1,std::memory_order_relaxed);
    const long long leadMin=s.leadMinFrames.exchange(1LL<<40,std::memory_order_relaxed);
    const long long latMax=s.latMaxUs.exchange(-1,std::memory_order_relaxed);
    const unsigned long long cb=now.callbacks-last.callbacks,ln=now.latCount-last.latCount;
    GLOG("RENDER_DIAG_AU_AHEAD lead=%u callbacks=%llu early=%llu refused=%llu hints=%llu wakes=%llu inflight_ms=%.2f lead_mean_ms=%.2f "
         "lead_max_ms=%.2f lead_min_ms=%.2f lat_n=%llu lat_mean_ms=%.2f lat_max_ms=%.2f lat_overflow=%llu main_waits=%llu "
         "main_wait_ms=%.2f starved=%llu drops=%llu",was,cb,now.early-last.early,now.refused-last.refused,now.hints-last.hints,
         now.wakes-last.wakes,areaUs?double(now.inFlightFrameUs-last.inFlightFrameUs)/double(areaUs)/48.0:-1.0,
         cb?double(now.leadSum-last.leadSum)/double(cb)/48.0:-1.0,leadMax>=0?double(leadMax)/48.0:-1.0,
         leadMin<(1LL<<40)?double(leadMin)/48.0:-1.0,ln,ln?double(now.latSum-last.latSum)/double(ln)/1000.0:-1.0,
         latMax>=0?double(latMax)/1000.0:-1.0,now.latOverflow-last.latOverflow,now.mainWaits-last.mainWaits,
         double(now.mainWaitUs-last.mainWaitUs)/1000.0,now.starved-last.starved,s.drops.load(std::memory_order_relaxed));
    last=now;
    return lead;
}
