    // arithmetic indices of the vertices 0 .. n - 1 of every rule fetch: functions of the rule alone, grown as draws need them
    std::array<std::array<vfi::IndexTable,12>,std::size(vfi::Rules)> tables;
    std::array<std::vector<std::uint32_t>,12> indexScratch; // (a draw past vfi::TableLimit vertices)
    vfi::Taken taken,viaTaken;                              // the one copy of a stream's guest bytes (vfi::take)
    std::array<std::vector<std::uint8_t>,24> big,copies,composed; // layouts not kept; streams read through the Reader; streams read at several indices
