        const VkComponentMapping id{VK_COMPONENT_SWIZZLE_IDENTITY,VK_COMPONENT_SWIZZLE_IDENTITY,VK_COMPONENT_SWIZZLE_IDENTITY,VK_COMPONENT_SWIZZLE_IDENTITY};
        const VkImageUsageFlags frameUse=VK_IMAGE_USAGE_STORAGE_BIT|VK_IMAGE_USAGE_TRANSFER_DST_BIT|VK_IMAGE_USAGE_TRANSFER_SRC_BIT;
        const bool savedBase=baseResources;baseResources=false; // (failedImage frees partial images here)
        bool ok=makeImage(w,h,1,VK_FORMAT_R8G8B8A8_UNORM,frameUse,VK_IMAGE_ASPECT_COLOR_BIT,false,id,fi.frames[0]) &&
            makeImage(w,h,1,VK_FORMAT_R8G8B8A8_UNORM,frameUse,VK_IMAGE_ASPECT_COLOR_BIT,false,id,fi.frames[1]) &&
            makeImage(w,h,1,VK_FORMAT_R8G8B8A8_UNORM,frameUse,VK_IMAGE_ASPECT_COLOR_BIT,false,id,fi.mid) &&
            makeImage(fi.qw,fi.qh,1,VK_FORMAT_R32_SFLOAT,VK_IMAGE_USAGE_STORAGE_BIT,VK_IMAGE_ASPECT_COLOR_BIT,false,id,fi.lumaPrev) &&
            makeImage(fi.qw,fi.qh,1,VK_FORMAT_R32_SFLOAT,VK_IMAGE_USAGE_STORAGE_BIT,VK_IMAGE_ASPECT_COLOR_BIT,false,id,fi.lumaCur);
        baseResources=savedBase;
