        const VkBufferUsageFlags bufUse=VK_BUFFER_USAGE_STORAGE_BUFFER_BIT|VK_BUFFER_USAGE_TRANSFER_DST_BIT;
        ok=ok && makeBuffer(blocks*4,bufUse,fi.coarse) && makeBuffer(blocks*4,bufUse,fi.fine) && makeBuffer(blocks*8,bufUse,fi.motion);
        std::array<VkDescriptorSetLayoutBinding,8> b{};
        for(unsigned i=0;i<8;++i){b[i].binding=i;b[i].descriptorCount=1;b[i].stageFlags=VK_SHADER_STAGE_COMPUTE_BIT;
            b[i].descriptorType=(i==4 || i==6 || i==7)?VK_DESCRIPTOR_TYPE_STORAGE_BUFFER:VK_DESCRIPTOR_TYPE_STORAGE_IMAGE;}
        VkDescriptorSetLayoutCreateInfo l{};l.sType=VK_STRUCTURE_TYPE_DESCRIPTOR_SET_LAYOUT_CREATE_INFO;l.bindingCount=8;l.pBindings=b.data();
        ok=ok && vkCreateDescriptorSetLayout(d.device,&l,nullptr,&fi.setLayout)==VK_SUCCESS;
        VkPushConstantRange range{VK_SHADER_STAGE_COMPUTE_BIT,0,sizeof(FiPush)};
        VkPipelineLayoutCreateInfo pl{};pl.sType=VK_STRUCTURE_TYPE_PIPELINE_LAYOUT_CREATE_INFO;pl.setLayoutCount=1;pl.pSetLayouts=&fi.setLayout;
        pl.pushConstantRangeCount=1;pl.pPushConstantRanges=&range;
        ok=ok && vkCreatePipelineLayout(d.device,&pl,nullptr,&fi.layout)==VK_SUCCESS;
        const std::array<VkDescriptorPoolSize,2> sizes{{{VK_DESCRIPTOR_TYPE_STORAGE_IMAGE,10},{VK_DESCRIPTOR_TYPE_STORAGE_BUFFER,6}}};
        VkDescriptorPoolCreateInfo pc{};pc.sType=VK_STRUCTURE_TYPE_DESCRIPTOR_POOL_CREATE_INFO;pc.maxSets=2;pc.poolSizeCount=2;pc.pPoolSizes=sizes.data();
        ok=ok && vkCreateDescriptorPool(d.device,&pc,nullptr,&fi.pool)==VK_SUCCESS;
