            readyMid=displayRampActive?post::opaqueRgbaRamped(static_cast<const std::uint8_t*>(s.midReadback.mapped),s.readbackBytes,displayRamp):
                opaqueRgba(static_cast<const std::uint8_t*>(s.midReadback.mapped),s.readbackBytes);
