        screenSpaceDraws=!switchFile("diag-generic-no-screen-space"); GLOG("RENDER_GENERIC_V157 screen_space=%d",int(screenSpaceDraws));
        frameInterp=switchFile("diag-generic-frame-interp");v234::interpOn.store(frameInterp,std::memory_order_release); GLOG("RENDER_GENERIC_V158 frame_interp=%d",int(frameInterp));
