    // v41: the pixel "shader" of a draw with no pixel code (no SPIR-V, no outputs, no samplers).
    const PackEntry nullPixel{0,1,0,0,0,{},0,0,{}};
    VkShaderModule module(const PackEntry& e) {
        auto& m=modules[&e];
        if(!m) {
            VkShaderModuleCreateInfo c{};c.sType=VK_STRUCTURE_TYPE_SHADER_MODULE_CREATE_INFO;c.codeSize=std::size_t{e.spirvWords}*4;
            c.pCode=reinterpret_cast<const std::uint32_t*>(pack.data()+e.spirvOffset);
            m=graphicsModule(c.pCode,e.spirvWords); // v294
        }
        return m;
    }
    std::vector<std::uint32_t> entryWords(const PackEntry& e) const {
        const auto* w=reinterpret_cast<const std::uint32_t*>(pack.data()+e.spirvOffset);return {w,w+e.spirvWords};
    }
    // v85: a pixel entry's discard analysis and whether its alpha test can be generalized (first use only).
    const PixelInfo& pixel(const PackEntry& e) {
        if(v363FlatMaps) { // v363: the entry front
            if(const auto& f=v363Entry(e);f.pixel) {
                ++v363Stats.entryHits;
                v363Verify(pixelInfo.find(&e)!=pixelInfo.end() && &pixelInfo.find(&e)->second==f.pixel,"pixel");
                return *f.pixel;
            }
            ++v363Stats.entryMisses;
            const auto& info=pixelMapped(e);
            v363Entry(e).pixel=&info;
            return info;
        }
        return pixelMapped(e);
    }
    const PixelInfo& pixelMapped(const PackEntry& e) {
        const auto it=pixelInfo.find(&e);if(it!=pixelInfo.end())return it->second;
        PixelInfo info;
        if(&e!=&nullPixel && e.spirvWords) {
            const auto words=entryWords(e);
            info.discard=spirv::analyzePixelDiscards(words,state::AlphaWordThreshold);
            info.fragCoord=rsLoadsFragCoord(words); // fsr-modes
            info.generic=info.discard.alphaKills>0;
            if(!info.discard.valid)note("pixel-spirv-unparsed");
            else if(!info.discard.alphaKills)note("pixel-no-alpha-site");
        }
        return pixelInfo.emplace(&e,info).first->second;
    }
    // v85: a pixel module variant: PsGeneric the generalized alpha test, PsLate without EarlyFragmentTests.
    VkShaderModule module(const PackEntry& e,unsigned variant) {
        if(!variant || &e==&nullPixel)return module(e);
        auto& m=variantModules[variant&15][&e]; // (fsr-modes: 16 with PsScaled)
        if(m)return m;
        auto words=entryWords(e);
        if(variant&PsGeneric) {
            auto r=spirv::generalizeAlphaTest(words,state::AlphaWordS,state::AlphaWordE,state::AlphaWordC,state::AlphaWordThreshold);
            if(!r.code){note("alpha-generalize-refused",r.why);return VK_NULL_HANDLE;}
            words=std::move(*r.code);++v85.genericModules;
        }
        if(variant&PsLate){words=spirv::withoutEarlyFragmentTests(words);++v85.lateModules;}
        if(variant&PsRound)dfRoundWords(words); // depth-float (diag-df-round)
        rsFragWords(words,variant); // fsr-modes (PsScaled only; out of line): last, so that every FragCoord load (the rounding stage's too) is in guest pixels
        m=graphicsModule(words.data(),words.size()); // v294
        return m;
    }
    // depth-float (diag-df-round): the module's fragment depth rounded to 20e4 (spirv_depth_round.h). A module the rewrite refuses
    // keeps its words (noted, counted: the draw's depth stays unrounded, as with the switch off).
    void dfRoundWords(std::vector<std::uint32_t>& words) {
        auto r=spirv::roundFragmentDepth(words);
        if(!r.code){note("df-round-refused",r.why);++dfRoundRefused;return;}
        words=std::move(*r.code);++(r.exported?dfRoundExported:dfRoundAdded);
    }
    VkShaderModule dfRoundNull() { // the fragment stage of a rounded depth-only draw (no pixel shader), made once
        if(!dfNullModule){const auto w=spirv::depthRoundNullModule();dfNullModule=graphicsModule(w.data(),w.size());}
        return dfNullModule;
    }
    // v85 switches (read with the others every 30 presents).
    void pollV85Switches(bool first) {
        const auto has=[](const char* name){char path[160];std::snprintf(path,sizeof path,RECOMP_APP_PATH("/private-trace/%s"),name);
            return access(path,F_OK)==0;};
        const bool lateOn=!has("diag-generic-early-tests"),legacyA=has("diag-generic-legacy-alpha"),a2cOn=!has("diag-generic-no-a2c"),
            guardOn=!has("diag-generic-legacy-blend");
        if(lateOn!=lateTests || legacyA!=legacyAlpha || a2cOn!=alphaToMask || guardOn!=blendGuard || first)
            GLOG("RENDER_GENERIC_V85_MODE late_tests=%u alpha_functions=%u alpha_to_mask=%u blend_guard=%u",unsigned(lateOn),
                 unsigned(!legacyA),unsigned(a2cOn && !legacyA),unsigned(guardOn));
        lateTests=lateOn;legacyAlpha=legacyA;alphaToMask=a2cOn;blendGuard=guardOn;
    }
    bool hostBlends(VkFormat f) {
        if(!state::blendSupportOptional(f))return true;
        const auto it=blendSupport.find(int(f));if(it!=blendSupport.end())return it->second;
        VkFormatProperties p{};vkGetPhysicalDeviceFormatProperties(d.physical,f,&p);
        const bool ok=(p.optimalTilingFeatures&VK_FORMAT_FEATURE_COLOR_ATTACHMENT_BLEND_BIT)!=0;
        blendSupport[int(f)]=ok;
        {char b[48];std::snprintf(b,sizeof b,"vkformat=%d blend=%u",int(f),unsigned(ok));note("host-blend-support",b);}
        return ok;
    }

    // v78: the device shadow as bytes in place (a DrawInput's stateBytes) or a vector's (v71: the vector only).
