        rsFits=rscale::fits(rsSetting.k,l.maxImageDimension2D,std::min(l.maxViewportDimensions[0],l.maxViewportDimensions[1]),std::uint32_t(ScreenSpaceExtent));
        rsK=rsFits?rsSetting.k:rscale::One;rsPassK=rscale::One;
