    [[gnu::noinline]] unsigned rsbPresentW(unsigned width,bool direct) const noexcept {return recomp::gpu::direct::rsb::presentExtent(width,rsbW,direct);}
    [[gnu::noinline]] unsigned rsbPresentH(unsigned height,bool direct) const noexcept {return recomp::gpu::direct::rsb::presentExtent(height,rsbH,direct);}
