        const auto h=rscale::hostCopy({g[0],g[1],g[2],g[3],std::uint32_t(std::max(g[4],0)),std::uint32_t(std::max(g[5],0))},src.k,
            rsHostW(src),rsHostH(src),src.k==dst.k?rsHostW(dst):rscale::extent(dst.width,src.k),src.k==dst.k?rsHostH(dst):rscale::extent(dst.height,src.k));
