        barrier(); // the buffer is read and written by transfer and compute in turn (buffers are not in the targeted lists)
        VkBufferImageCopy in{};in.bufferOffset=m.source;in.imageSubresource={VK_IMAGE_ASPECT_COLOR_BIT,0,0,1};in.imageExtent={r.image.width,r.image.height,1};
        vkCmdCopyImageToBuffer(cmd,r.image.image,VK_IMAGE_LAYOUT_GENERAL,m.buffer.buffer,1,&in);
        barrier();
