        const std::uint8_t* qd=qs+std::size_t{ns}*sizeof(Vkw4Stream);const std::uint8_t* qe=qd+std::size_t{nad}*sizeof(spirv::InputAdapt);
        auto& attrs=pipelineState.attributes;streamCount=0;adaptCount=0;
