    bool clear(const ClearInput& in,const char** why) {
        auto* p=takeOp();p->kind=KindClear;p->clear=in;
        p->haveState=in.state && in.state->size()>=13860;
        if(p->haveState){p->state.assign(in.state->begin(),in.state->end());p->clear.state=&p->state;}else p->clear.state=nullptr;
        {std::lock_guard lock(m);++counters.clears;}
        if(pipe.push({p,KindClear,true})){if(lockstep)return lockstepResult(why);if(why)*why="generic-clear-queued";return true;}
        recycle(p);return false;
    }
    bool resolve(const ResolveInput& in,const char** why) {
        auto* p=takeOp();p->kind=KindResolve;p->resolve=in;
        p->haveState=in.state!=nullptr;
        if(p->haveState){p->state.assign(in.state->begin(),in.state->end());p->resolve.state=&p->state;}else p->resolve.state=nullptr;
        {std::lock_guard lock(m);++counters.resolves;}
        if(pipe.push({p,KindResolve,true})){if(lockstep)return lockstepResult(why);if(why)*why="generic-resolve-queued";return true;}
        recycle(p);return false;
    }
    void invalidate(std::uint32_t address,std::uint32_t bytes) {
        auto* p=takeOp();p->kind=KindInvalidate;p->address=address;p->bytes=bytes;
        {std::lock_guard lock(m);++counters.controls;}
        if(!pipe.push({p,KindInvalidate,false}))recycle(p);
    }
    // v177: the queued present. present() pushes the frame's present (queuePresent) and returns the image of the previous
    // one, which the worker left here (under rendererMutex). lastPresentSeq: the queue sequence of the newest queued
    // present (render thread only).
    struct Mailbox {std::optional<std::vector<std::uint8_t>> image;const char* why=nullptr;bool ready=false;std::uint64_t presents=0;} mailbox;
    std::uint64_t lastPresentSeq=0;
    bool queuePresent(std::uint32_t address,unsigned width,unsigned height) {
        auto* p=takeOp();p->kind=KindPresent;p->address=address;p->width=width;p->height=height;
        lat2BoostWorker(); // latency-path L1 (before the push: the worker's restore after this item always comes later)
        const auto seq=pipe.push({p,KindPresent,true});
        if(!seq){recycle(p);return false;}
        recomp::diag::timeline::mark(recomp::diag::timeline::PresentQueued,lat2Behind(seq),std::uint32_t(seq)); // v318 (lat2: arg = the worker's backlog)
        recomp::v337::noteQueued(std::uint32_t(seq)); // v337
        recomp::pace::queued(std::uint32_t(seq)); // pace-caps (lane A): the frame's slot follows its tag (a load and a return without a cap)
        lastPresentSeq=seq;return true;
    }
    // v183: `work` runs on the renderer thread after every item queued before it (FIFO over all producers).
    std::uint64_t workItems=0; // (renderer thread)
    bool queueWork(std::function<void()> work) {
        auto* p=takeOp();p->kind=KindWork;p->work=std::move(work);
        if(pipe.push({p,KindWork,false}))return true;
        auto w=std::move(p->work);recycle(p);if(w)w();return true; // (pipeline stopping: run it now)
    }
    // v211: as queueWork, returning the item's queue sequence (0: it ran inline).
    std::uint64_t queueWorkMarked(std::function<void()> work) {
        auto* p=takeOp();p->kind=KindWork;p->work=std::move(work);
        if(const auto seq=pipe.push({p,KindWork,false}))return seq;
        auto w=std::move(p->work);recycle(p);if(w)w();return 0;
    }
    bool reached(std::uint64_t seq) const {return pipe.executed()>=seq;}
    // v123: after a present: the next frame's slot is prepared on the renderer thread (Renderer::prepareNextSlot).
    void prepareNext() {
        auto* p=takeOp();p->kind=KindPrepare;
        if(!pipe.push({p,KindPrepare,false})){recycle(p);return;}
        if(lockstep)drainFor(Reason::Other); // (host tests inspect the renderer and the mock between calls)
    }
    void unlock(const std::array<std::uint32_t,6>& fetch) {
        auto* p=takeOp();p->kind=KindUnlock;p->fetch=fetch;
        {std::lock_guard lock(m);++counters.controls;}
        if(!pipe.push({p,KindUnlock,false}))recycle(p);
    }
    // v31 contract, on the guest side (the renderer's code cache belongs to the renderer thread).
    bool vertexKnown(const std::vector<std::uint8_t>& code) {
        std::lock_guard lock(m);trimCaches();
        const auto it=r.shaders.find(contentCodes.canonical(code));
        return it!=r.shaders.end() && it->second->stage==0;
    }
    // After a present (under rendererMutex): per-frame validations start over (ownership is checked once per frame,
    // as v109's binding cache verified each texture once per frame).
