    std::vector<ConstBlock*> freeBlocks;
    struct LastBlock {unsigned id1=0;std::uint64_t version=0;} lastVc,lastPc; // (under m; v253: id + 1, 0 = none)
    ConstBlock* takeBlock(){std::lock_guard lock(poolMutex);if(freeBlocks.empty())return new ConstBlock;auto* b=freeBlocks.back();freeBlocks.pop_back();return b;}
    // v233: the capture side's own free lists (under m), refilled from the shared ones (poolMutex, where the renderer thread
