    // to three times (v227 outdoor profile: std::mutex lock/unlock 4.5% of the render thread, pool and queue locks it shares
    // with the renderer thread). Same packets and blocks, another order. diag-v233-baseline: v232's per-take locking.
    std::vector<std::pair<DrawPacket*,unsigned>> localDraws;std::vector<unsigned> localBlocks; // (under m; v253: block ids)
    std::vector<ConstBlock*> blockById;std::vector<unsigned> blockRefs;       // v253 (under m)
    std::vector<std::array<unsigned,2>> slotBlocks;                           // v253 (under m): per packet slot, vc/pc id + 1
    unsigned currentSlot=~0u;                                                 // v253 (under m): the packet capture() fills
    // v366a: per packet slot (under m), parallel to slotBlocks: the code generation its raw pointers point into (0: none) and whether
    // its shared_ptr code fields may be non-empty (set by a capture with the switch off, or for unversioned code).
    struct SlotCode {std::uint32_t gen=0;bool shared=false;};
    std::vector<SlotCode> slotCode;
