                cpu_set_t set;CPU_ZERO(&set);RECOMP_TOPOLOGY_ADD_CPUS(set,recomp_topology::roles().little);(void)sched_setaffinity(0,sizeof set,&set); // topology lane: the little role (Thor: A510 cores 0-2, as the v139 prewarm)
                (void)setpriority(PRIO_PROCESS,int(gettid()),10); // (this thread only)
#endif
