            const auto setCode=[reassign](std::shared_ptr<const std::vector<std::uint8_t>>& dst,const std::shared_ptr<const std::vector<std::uint8_t>>& src){
                if(reassign || dst!=src)dst=src;};
            // v366a (switch on): the packet points at the cached snapshot (alive while its generation is: sc.gen); an unversioned
            // snapshot (a fresh one in the scratch) is owned by the packet's shared_ptr, as before
            const auto own=[&sc,&totals=v366Totals](std::shared_ptr<const std::vector<std::uint8_t>>& dst,const CodeInfo& c,std::uint64_t version) {
#if !defined(RECOMP_V366_MUTANT_SCRATCH_UNOWNED) // (test mutant: the packet does not own it; the next unversioned capture frees it)
                if(!version){dst=c.bytes;sc.shared=true;++totals.scratchOwned;}
#else
                (void)dst;(void)version;
#endif
                return c.bytes.get();};
            auto& id=codeInfo(*in.vertexIdentity,in.vertexIdentityVersion,scratchOf(0));
            if(v366)p.rawIdentity=own(p.identity,id,in.vertexIdentityVersion);else setCode(p.identity,id.bytes);
            CodeInfo* eff=nullptr;
            if(in.vertexEffective==in.vertexIdentity){if(v366)p.rawEffective=p.rawIdentity;else setCode(p.effective,p.identity);eff=&id;}
            else if(in.vertexEffective){eff=&codeInfo(*in.vertexEffective,in.vertexEffectiveVersion,scratchOf(1));
                if(v366)p.rawEffective=own(p.effective,*eff,in.vertexEffectiveVersion);else setCode(p.effective,eff->bytes);}
            else if(v366)p.rawEffective=nullptr;else p.effective.reset(); // v329 (a pooled packet keeps its previous pointers: the absent ones are cleared here)
            if(!in.pixelCode){if(v366)p.rawPixel=nullptr;else p.pixel.reset();} // v329
            const PackEntry* found=packLookup(id.canonical); // v264 (the same map lookups through packLookup's front)
            if(!found && eff && in.vertexEffective!=in.vertexIdentity)found=packLookup(eff->canonical);
            if(!found && in.vertexAlternates) {
                p.alternates=*in.vertexAlternates;p.haveAlternates=true;
                for(const auto& alt:p.alternates)if(const auto* a=packLookup(contentCodes.canonical(alt))){found=a;break;}
            }
            const PackEntry* vs=found && found->stage==0?found:nullptr;
            const PackEntry* ps=nullptr;std::uint32_t psSamplers=0;bool psOk=true;
            if(in.pixelCode) {
                auto& pix=codeInfo(*in.pixelCode,in.pixelVersion,scratchOf(2));
                if(v366)p.rawPixel=own(p.pixel,pix,in.pixelVersion);else setCode(p.pixel,pix.bytes);
                const PackEntry* pe=packLookup(pix.canonical); // v264
                if(!pe || pe->stage!=1)psOk=false;
                else {
                    ps=pe;psSamplers=ps->samplers;
                    if(const auto g=r.gradientShaders.find(pix.canonical);g!=r.gradientShaders.end()) // either module (gradientFix)
                        psSamplers=(g->second.fixed?g->second.fixed->samplers:0u)|(g->second.original?g->second.original->samplers:0u);
                }
            }
            if(!v366) { // v366a, the switch off: the shared_ptrs own the code, as before (the renderer thread reads these copies of them)
                p.rawIdentity=p.identity.get();p.rawEffective=p.effective.get();p.rawPixel=p.pixel.get();sc.shared=true;
                if(sc.gen){releaseCodeGen(sc.gen);sc.gen=0;}
            }
