// v134 (diagnostic): a present more than 80 ms after the previous one logs what the frame did (deltas since that present):
// its draws, texture uploads and bytes, pipelines and images created, resolves, the GPU wait at present, maintenance passes,
// the render thread's time in renderer drains (ring barriers, this present). The rest of the interval is guest-side
// (game code, permit waits, exclusive spans). At most one line per 250 ms.
std::atomic<std::uint64_t> slowBarrierNs{0}; // v134 (diagnostic): render-thread time in guestReadBarrier drains
struct SlowFrameMark {async::Clock::time_point t{};std::uint64_t draws=0,textures=0,texBytes=0,pipelines=0,images=0,resolves=0,waitNs=0,maintains=0,barrierNs=0;
                     std::array<std::uint64_t,6> sites{};}; // v137: per-site images
SlowFrameMark slowPrev;async::Clock::time_point slowLastLog{};std::uint64_t slowFrames=0,slowPresents=0;
// v134/v177: the slow-frame line (a present more than 80 ms after the previous one), under rendererMutex.
void slowFrameStats(Renderer& r,async::Clock::time_point start,async::Clock::time_point drained) {
    const SlowFrameMark now{start,r.counters.draws,r.counters.textures,r.slowTexBytes,r.counters.pipelines,r.slowImagesMade,r.counters.resolves,
                            r.slowWaitNs,r.slowMaintains,slowBarrierNs.load(std::memory_order_relaxed),r.slowImageSite};
    ++slowPresents;
    if(!(slowPresents%1200))GLOG("RENDER_GENERIC_RECIPES_STATS presents=%llu pipelines=%llu recorded=%llu variant=%llu unrecordable=%llu duplicate=%llu write_failures=%llu prewarm_compiled=%u prewarm_failed=%u prewarm_skipped=%u prewarm_done=%u", // v142
        (unsigned long long)slowPresents,(unsigned long long)r.counters.pipelines,(unsigned long long)r.recipesRecorded,(unsigned long long)r.recipesVariant,
        (unsigned long long)r.recipesUnrecordable,(unsigned long long)r.recipesDuplicate,(unsigned long long)r.recipeWriteFailures,
        r.prewarmCompiled.load(),r.prewarmFailed.load(),r.prewarmSkipped.load(),unsigned(r.prewarmDone.load()));
    if(slowPrev.t!=async::Clock::time_point{}) {
        const double interval=double(async::nanos(slowPrev.t,start))*1e-6;
        if(interval>80.0) {
            ++slowFrames;
            if(async::nanos(slowLastLog,start)>250'000'000ll) {
                slowLastLog=start;
                GLOG("RENDER_GENERIC_SLOW_FRAME interval_ms=%.1f present_ms=%.2f drain_ms=%.2f barrier_ms=%.2f gpu_wait_ms=%.2f draws=%llu textures=%llu "
                     "tex_kb=%llu pipelines=%llu images=%llu resolves=%llu maintains=%llu slow=%llu/%llu img_sites=%llu/%llu/%llu/%llu/%llu/%llu",interval,
                     double(async::nanos(start,async::Clock::now()))*1e-6,double(async::nanos(start,drained))*1e-6,(now.barrierNs-slowPrev.barrierNs)*1e-6,
                     (now.waitNs-slowPrev.waitNs)*1e-6,(unsigned long long)(now.draws-slowPrev.draws),(unsigned long long)(now.textures-slowPrev.textures),
                     (unsigned long long)((now.texBytes-slowPrev.texBytes)/1024),(unsigned long long)(now.pipelines-slowPrev.pipelines),
                     (unsigned long long)(now.images-slowPrev.images),(unsigned long long)(now.resolves-slowPrev.resolves),
                     (unsigned long long)(now.maintains-slowPrev.maintains),(unsigned long long)slowFrames,(unsigned long long)slowPresents,
                     (unsigned long long)(now.sites[0]-slowPrev.sites[0]),(unsigned long long)(now.sites[1]-slowPrev.sites[1]),
                     (unsigned long long)(now.sites[2]-slowPrev.sites[2]),(unsigned long long)(now.sites[3]-slowPrev.sites[3]),
                     (unsigned long long)(now.sites[4]-slowPrev.sites[4]),(unsigned long long)(now.sites[5]-slowPrev.sites[5]));
            }
        }
    }
    slowPrev=now;
}
