// v319 (measurement only): called by the draw-entry hooks (renderer_boundary_trace.cpp) before the game's commit consumes the
// device's dirty words; the next chained capture on this thread compares its state diff against them (AsyncFront::v319Check).
extern "C" void recomp_v319_note_commit(const std::uint8_t* device) noexcept {
    using namespace recomp::gpu::generic;
    if(!device || !recompV319Shadow.load(std::memory_order_relaxed))return;
    v319Pending.orIn(v319::readDirty(device));v319Snapped=true;
}
